function validate([n, commands]) {
  if (!Number.isInteger(n) || n < 2 || n > 10) return 'n is a whole number from 2 to 10.';
  if (!Array.isArray(commands) || commands.length < 1 || commands.length > 100) return 'commands needs 1 to 100 entries.';
  const moves = { UP: [-1, 0], DOWN: [1, 0], LEFT: [0, -1], RIGHT: [0, 1] };
  let row = 0, col = 0;
  for (const command of commands) {
    if (!Object.hasOwn(moves, command)) return 'Each command is "UP", "RIGHT", "DOWN" or "LEFT".';
    row += moves[command][0];
    col += moves[command][1];
    if (row < 0 || row >= n || col < 0 || col >= n) return 'The commands must keep the snake inside the grid.';
  }
  return null;
}

