function finalPositionOfSnake(n, commands) {
  // Build the numbered grid, walk on it with direction vectors, and read the label of the final cell.
  const grid = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => i * n + j));
  const step = { UP: [-1, 0], DOWN: [1, 0], LEFT: [0, -1], RIGHT: [0, 1] };
  let cell = [0, 0];
  for (const c of commands) cell = [cell[0] + step[c][0], cell[1] + step[c][1]];
  return grid[cell[0]][cell[1]];
}

