function generate(rand, size) {
  const n = size === 'large' ? 2 + Math.floor(rand() * 9) : 2 + Math.floor(rand() * 3);
  const count = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  const moves = { UP: [-1, 0], DOWN: [1, 0], LEFT: [0, -1], RIGHT: [0, 1] };
  const commands = [];
  let row = 0, col = 0;
  while (commands.length < count) {
    // Choose only moves that keep the snake on the grid.
    const options = Object.keys(moves).filter(m => {
      const r = row + moves[m][0], c = col + moves[m][1];
      return r >= 0 && r < n && c >= 0 && c < n;
    });
    const move = options[Math.floor(rand() * options.length)];
    commands.push(move);
    row += moves[move][0];
    col += moves[move][1];
  }
  return [n, commands];
}
